-- ==============================================
-- Migration: 2FA recovery codes (B0.7, D-23, AC-40)
-- Date: 2026-11-08
--
-- Supabase Auth has no recovery codes, so BookVault keeps its own: generated by
-- FastAPI from a CSPRNG, shown once, stored only as SHA-256 hashes, single use.
-- Using one deletes the user's TOTP factors and forces re-enrollment.
-- Only the API role (as the user, RLS) reads or writes them.
--
-- ROLLBACK (run manually):
--   DROP TABLE public.mfa_recovery_codes;
-- ==============================================

CREATE TABLE public.mfa_recovery_codes (
    id         UUID PRIMARY KEY DEFAULT public.uuid_generate_v7(),
    user_id    UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    code_hash  TEXT NOT NULL CHECK (code_hash ~ '^[0-9a-f]{64}$'),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    used_at    TIMESTAMPTZ NULL,
    CONSTRAINT mfa_recovery_codes_user_hash UNIQUE (user_id, code_hash)
);

COMMENT ON TABLE public.mfa_recovery_codes IS
    'Hashed single-use 2FA recovery codes (B0.7). Plaintext is shown once and never stored.';

ALTER TABLE public.mfa_recovery_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mfa_recovery_codes FORCE ROW LEVEL SECURITY;
REVOKE ALL ON public.mfa_recovery_codes FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, DELETE ON public.mfa_recovery_codes TO bookvault_api;
GRANT UPDATE (used_at) ON public.mfa_recovery_codes TO bookvault_api;

CREATE POLICY mfa_recovery_codes_api_own ON public.mfa_recovery_codes FOR ALL TO bookvault_api
    USING (user_id = public.app_user_id())
    WITH CHECK (user_id = public.app_user_id());
